const { monitorEventLoopDelay, performance } = require('node:perf_hooks');

const h = monitorEventLoopDelay({ resolution: 20 });
h.enable();

let lastElu = performance.eventLoopUtilization();
setInterval(() => {
  const elu = performance.eventLoopUtilization(lastElu); // delta since last
  lastElu = performance.eventLoopUtilization();
  console.log({
    p99DelayMs: h.percentile(99) / 1e6, // histogram is in nanoseconds
    maxDelayMs: h.max / 1e6,
    utilization: elu.utilization.toFixed(2), // 0..1
  });
  h.reset();
}, 10_000).unref();

