function processInChunks(items, handle, chunkSize = 1000) {
  return new Promise((resolve) => {
    let i = 0;
    function next() {
      const end = Math.min(i + chunkSize, items.length);
      for (; i < end; i++) handle(items[i]);
      if (i < items.length) setImmediate(next); // let I/O run
      else resolve();
    }
    next();
  });
}

// main.js
const { Worker } = require('node:worker_threads');

function runInWorker(data) {
  return new Promise((resolve, reject) => {
    const w = new Worker('./heavy.js', { workerData: data });
    w.once('message', resolve);
    w.once('error', reject);
    w.once('exit', (code) => { if (code !== 0) reject(new Error(`exit ${code}`)); });
  });
}

